#!/usr/bin/env node
/**
 * cng-prebuild-preflight — refuse a build that a leftover prebuild would poison,
 * with an instruction instead of a baffling error.
 *
 * WHY THIS EXISTS (ticket e2e-prebuild-bricks-eas-build, proven on packing-list
 * 2026-08-26, second instance on grocery-list the same night).
 *
 * Our apps are CNG (continuous native generation): `ios/` and `android/` are
 * gitignored build artifacts, regenerated by `expo prebuild`. Anything that
 * prebuilds on this machine — the two-device e2e suite, a bare `expo prebuild`,
 * a debug run — leaves those dirs behind. EAS then detects a native dir and
 * switches to the BARE workflow, and from there two things happen depending on
 * the app's runtimeVersion:
 *
 *   • policy form (`{policy:'appVersion'}` — grocery-list, packing-list,
 *     workout-timer, home-maintenance) → a HARD failure on every subsequent
 *     `eas build --local`, both platforms: "CommandError: You're currently using
 *     the bare workflow, where runtime version policies are not supported."
 *     Nothing in that message mentions a directory, so the app's build pipeline
 *     is simply dead on this machine until someone works it out. It blocked the
 *     t5 upgrade pass for a night.
 *   • literal form (`'1.0.0'` — tend) → NO error at all. EAS quietly builds from
 *     the stale on-disk tree, so `app.json` edits never reach the binary. That is
 *     the silent half (ticket tend-persisted-ios-dir) — it left a tend build in
 *     Missing Compliance, undelivered, for days.
 *
 * Both halves are the same root cause, so this guard fires on the pairing that
 * defines it: a native dir that git does NOT track, in a repo that ignores it.
 * An untracked native dir is never intent — it is residue.
 *
 * WHY REFUSE RATHER THAN CLEAN UP SILENTLY. A build is expensive and a store
 * binary is irreversible; deleting a native tree someone is mid-debug on is
 * worse than stopping. `--park` is the one-command remedy, and it MOVES the tree
 * out of the repo (to ~/.ja-prebuild-leftovers/) rather than deleting it, so a
 * future e2e run can move one back instead of paying for another prebuild.
 * Renaming in place does not work: .gitignore pins the exact paths `/ios` and
 * `/android`, so a renamed leftover shows up as untracked noise.
 *
 *   node scripts/lib/cng-prebuild-preflight.mjs <appDir>          # gate: exit 1 on residue
 *   node scripts/lib/cng-prebuild-preflight.mjs <appDir> --park    # park it, then exit 0
 *   node scripts/lib/cng-prebuild-preflight.mjs <appDir> --json
 *   node scripts/lib/cng-prebuild-preflight.mjs --self-test
 */

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const PARK_ROOT = path.join(os.homedir(), '.ja-prebuild-leftovers');
const PLATFORM_DIRS = ['ios', 'android'];

/**
 * PURE core (self-tested): the verdict for one app's native-dir posture.
 *
 * `natives` = [{ platform, present, tracked }]. `tracked` means git tracks files
 * under that dir — a DELIBERATELY persisted native project, which is a different
 * (and legitimate) posture this guard must not touch.
 */
export function prebuildPostureVerdict({ app = 'app', natives = [], runtimeVersion } = {}) {
  const residue = natives.filter((n) => n.present && !n.tracked);
  if (!residue.length) {
    return { ok: true, residue: [], message: `${app}: no leftover native dirs — CNG posture intact` };
  }
  const policy = runtimeVersion && typeof runtimeVersion === 'object' ? runtimeVersion.policy : null;
  const consequence = policy
    ? `every \`eas build --local\` for ${app} will FAIL with "You're currently using the bare workflow, where runtime version policies are not supported" (app.json runtimeVersion is the policy form, {policy:'${policy}'}) — the error never mentions a directory`
    : `EAS will switch to the BARE workflow and build from this stale tree, SILENTLY — app.json changes (infoPlist, compliance keys) will not reach the binary. This is the failure that left a build undelivered in Missing Compliance for days`;
  return {
    ok: false,
    residue,
    message: [
      `${app}: REFUSING TO BUILD — ${residue.length} leftover prebuild dir(s) that git does not track: ${residue.map((r) => `${r.platform}/`).join(', ')}.`,
      `Because of them, ${consequence}.`,
      `These apps are CNG: ios/ and android/ are regenerated artifacts, so an untracked one is residue from an e2e run, a bare \`expo prebuild\`, or a debug build — never intent.`,
      `Remedy: re-run this with --park (moves each tree to ${PARK_ROOT}/<app>-<platform>-<date> so a future e2e run can move it back, rather than deleting it). Renaming in place does NOT work — .gitignore pins the exact paths /ios and /android, so a renamed leftover reads as untracked noise.`,
    ].join('\n'),
  };
}

/** PURE (self-tested): the parking path for one leftover, avoiding a collision. */
export function parkPathFor(app, platform, { date = new Date(), taken = () => false, root = PARK_ROOT } = {}) {
  const stamp = `${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, '0')}${String(date.getDate()).padStart(2, '0')}`;
  const base = path.join(root, `${app}-${platform}-${stamp}`);
  if (!taken(base)) return base;
  for (let n = 2; n < 100; n++) {
    const candidate = `${base}-${n}`;
    if (!taken(candidate)) return candidate;
  }
  return `${base}-${Date.now()}`;
}

/** Does git track anything under <appDir>/<dir>? Unknown (not a repo) reads as untracked. */
function gitTracks(appDir, dir) {
  try {
    const out = execFileSync('git', ['-C', appDir, 'ls-files', '--', dir], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    return out.trim().length > 0;
  } catch { return false; }
}

/** Read the app's declared runtimeVersion (policy object, literal string, or undefined). */
function readRuntimeVersion(appDir) {
  try { return JSON.parse(fs.readFileSync(path.join(appDir, 'app.json'), 'utf8'))?.expo?.runtimeVersion; } catch { return undefined; }
}

/** IMPURE: inspect one app dir and return the pure verdict. */
export function checkPrebuildPosture(appDir) {
  const app = path.basename(path.resolve(appDir));
  const natives = PLATFORM_DIRS.map((platform) => ({
    platform,
    present: fs.existsSync(path.join(appDir, platform)),
    tracked: gitTracks(appDir, platform),
  }));
  return { ...prebuildPostureVerdict({ app, natives, runtimeVersion: readRuntimeVersion(appDir) }), app, natives };
}

/** IMPURE: move each leftover out of the repo. Returns [{ platform, to }]. */
export function parkLeftovers(appDir, verdict) {
  const moved = [];
  fs.mkdirSync(PARK_ROOT, { recursive: true });
  for (const r of verdict.residue) {
    const to = parkPathFor(verdict.app, r.platform, { taken: (p) => fs.existsSync(p) });
    fs.renameSync(path.join(appDir, r.platform), to);
    moved.push({ platform: r.platform, to });
  }
  return moved;
}

// ---------- self-test (pure logic only) ----------

function selfTest() {
  let f = 0;
  const ok = (c, m) => { if (!c) { f++; console.error(`  ✗ ${m}`); } else console.log(`  ✓ ${m}`); };
  const n = (platform, present, tracked) => ({ platform, present, tracked });

  const clean = prebuildPostureVerdict({ app: 'grocery-list', natives: [n('ios', false, false), n('android', false, false)], runtimeVersion: { policy: 'appVersion' } });
  ok(clean.ok === true, 'a CNG app with no native dirs passes');

  const policyResidue = prebuildPostureVerdict({ app: 'packing-list', natives: [n('ios', true, false), n('android', true, false)], runtimeVersion: { policy: 'appVersion' } });
  ok(policyResidue.ok === false && policyResidue.residue.length === 2, 'the packing-list shape fires for both platforms');
  ok(/bare workflow/.test(policyResidue.message) && /runtime version policies/.test(policyResidue.message),
    'the policy-form message quotes the exact EAS error, so the baffling one is decoded');
  ok(/--park/.test(policyResidue.message) && /\.ja-prebuild-leftovers/.test(policyResidue.message),
    'and names the one-command remedy plus where the tree goes');
  ok(/pins the exact paths/.test(policyResidue.message),
    'and warns that renaming in place does not work (the .gitignore trap)');

  const literalResidue = prebuildPostureVerdict({ app: 'tend', natives: [n('ios', false, false), n('android', true, false)], runtimeVersion: '1.0.0' });
  ok(literalResidue.ok === false && literalResidue.residue.length === 1, 'the tend shape (literal runtimeVersion, one leftover) still fires');
  ok(/SILENTLY/.test(literalResidue.message) && /Missing Compliance/.test(literalResidue.message),
    'the literal-form message explains the SILENT half, which has no error at all');
  ok(!/runtime version policies/.test(literalResidue.message),
    'and does not quote an error that app will never see');

  const tracked = prebuildPostureVerdict({ app: 'persisted', natives: [n('ios', true, true), n('android', true, true)] });
  ok(tracked.ok === true, 'a DELIBERATELY persisted native project (git-tracked) is left alone — different posture, not residue');

  const mixed = prebuildPostureVerdict({ app: 'mixed', natives: [n('ios', true, true), n('android', true, false)] });
  ok(mixed.ok === false && mixed.residue.length === 1 && mixed.residue[0].platform === 'android',
    'a tracked ios/ plus an untracked android/ flags only the residue');

  ok(prebuildPostureVerdict({}).ok === true, 'no input fails OPEN — this guard must never block a build it knows nothing about');

  const d = new Date(2026, 7, 26); // 2026-08-26, the night this happened
  ok(parkPathFor('packing-list', 'ios', { date: d, root: '/park' }) === '/park/packing-list-ios-20260826',
    'the park path matches the shape already on disk from that night');
  ok(parkPathFor('packing-list', 'ios', { date: d, root: '/park', taken: (p) => !p.endsWith('-2') }) === '/park/packing-list-ios-20260826-2',
    'a second park on the same day does not clobber the first');

  console.log(f === 0 ? '\ncng-prebuild-preflight self-test PASSED' : `\ncng-prebuild-preflight self-test FAILED (${f})`);
  process.exit(f === 0 ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1] === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.includes('--self-test')) selfTest();
  else {
    const dir = args.find((a) => !a.startsWith('--'));
    if (!dir) { console.error('Usage: cng-prebuild-preflight.mjs <appDir> [--park] [--json] | --self-test'); process.exit(2); }
    const verdict = checkPrebuildPosture(dir);
    if (verdict.ok) {
      if (args.includes('--json')) console.log(JSON.stringify(verdict, null, 2));
      process.exit(0);
    }
    if (args.includes('--park')) {
      const moved = parkLeftovers(dir, verdict);
      for (const m of moved) console.log(`parked ${m.platform}/ → ${m.to}`);
      if (args.includes('--json')) console.log(JSON.stringify({ ...verdict, parked: moved }, null, 2));
      process.exit(0);
    }
    console.error(verdict.message);
    if (args.includes('--json')) console.error(JSON.stringify(verdict, null, 2));
    process.exit(1);
  }
}
